INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0010',10,'Drinks after the walk','استراحت بعد از پیاده روی','در دورهمی بعدی گروه پیاده روی، استراحت می کنید. سارا که قبلا با او آشنا شده ای از نوشیدنی های میز به تو پیشنهاد می دهد.','A1-INTERACTION-CHOOSE-DRINK',420,'1a880caa430a86fc9582f6b5572bee442bc44803ca1576a8f8a1131c13086132','validated','{"outcomeFa":"می توانی پیشنهاد دو نوشیدنی را بفهمی و انتخابت را کوتاه و مودبانه بگویی.","scenarioFa":"در دورهمی بعدی گروه پیاده روی، استراحت می کنید. سارا که قبلا با او آشنا شده ای از نوشیدنی های میز به تو پیشنهاد می دهد. نقش تو روبی است.","prerequisiteOutcomeKeys":["A1-INTERACTION-ORDER-DRINK"],"curriculum":{"startingKnowledge":"early_a1_after_greetings","targetConstructions":[{"key":"EN-CONSTR-ITEM-OR-ITEM","form":"item + or + item?","meaningFa":"پرسیدن انتخاب بین دو چیز"}],"supportLanguage":[],"assessmentBoundary":"Visible guided speech is supported reading practice, not mastery or pronunciation certification. Choice tasks assess only their stated recognition or selection demand; transcript recall is not unseen listening.","transferPlan":{"mode":"same_lesson","intent":"Select a different drink in the walking-group scene after a modeled tea choice; reuse cafe language without continuing the cafe story."},"story":{"arcKey":"EN-A1-WALKING-GROUP","sceneKey":"EN-A1-SCENE-0010","learnerRoleKey":"ruby","participants":["ruby","sara"],"introducedCharacterKeys":[],"relationshipState":"already_known","continuesLessonKey":"EN-A1-L-0005","dependsOnLessonKeys":["EN-A1-L-0005"],"settingFa":"میز نوشیدنی گروه در پارک، بعد از پیاده روی","storyBeatFa":"روبی و سارا پس از آشنایی قبلی، زمان استراحت گروه را با هم می گذرانند."},"reviewLinks":[{"lessonKey":"EN-A1-L-0009","activityKeys":["A03","A04"],"learningDemand":"transfer","note":"Retrieve drink meanings in a changed offer and make a new choice."}]},"pilot":false,"batchKey":"EN-A1-STORY-10-01","audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
SET @lesson_id=(SELECT id FROM lessons WHERE level_id=@level_id AND lesson_key='EN-A1-L-0010' LIMIT 1);
DELETE FROM lesson_lexical_items WHERE lesson_id=@lesson_id;

-- Keep existing activities IDs; remove only keys absent from this Lesson source.
DELETE FROM activities WHERE lesson_id=@lesson_id AND activity_key NOT IN ('A01','A02','A03','A04','A05');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),5) FROM activities WHERE lesson_id=@lesson_id);
UPDATE activities SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

-- Keep existing lesson_turns IDs; remove only keys absent from this Lesson source.
DELETE FROM lesson_turns WHERE lesson_id=@lesson_id AND turn_key NOT IN ('T01','T02','T03','T04','T05');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),5) FROM lesson_turns WHERE lesson_id=@lesson_id);
UPDATE lesson_turns SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

